  2069  static void
  2070  node_free_body(Node* node)
  2071  {
  2072    if (IS_NULL(node)) return ;
  2073
  2074    switch (NODE_TYPE(node)) {
  2075    case NODE_STRING:
  2076      if (STR_(node)->capacity != 0 &&
  2077          IS_NOT_NULL(STR_(node)->s) && STR_(node)->s != STR_(node)->buf) {
  2078        xfree(STR_(node)->s);
  2079      }
  2080      break;
  2081
  2082    case NODE_LIST:
  2083    case NODE_ALT:
  2084      onig_node_free(NODE_CAR(node));
  2085      node = NODE_CDR(node);
  2086      while (IS_NOT_NULL(node)) {
  2087        Node* next = NODE_CDR(node);
  2088        onig_node_free(NODE_CAR(node));
  2089        xfree(node);
  2090        node = next;
  2091      }
  2092      break;
  2093
  2094    case NODE_CCLASS:
  2095      {
  2096        CClassNode* cc = CCLASS_(node);
  2097
  2098        if (cc->mbuf)
  2099          bbuf_free(cc->mbuf);
  2100      }
  2101      break;
  2102
  2103    case NODE_BACKREF:
  2104      if (IS_NOT_NULL(BACKREF_(node)->back_dynamic))
  2105        xfree(BACKREF_(node)->back_dynamic);
  2106      break;
  2107
  2108    case NODE_BAG:
  2109      if (NODE_BODY(node))
  2110        onig_node_free(NODE_BODY(node));
  2111
  2112      {
  2113        BagNode* en = BAG_(node);
  2114        if (en->type == BAG_IF_ELSE) {
  2115          onig_node_free(en->te.Then);
  2116          onig_node_free(en->te.Else);
  2117        }
  2118      }
  2119      break;
  2120
  2121    case NODE_QUANT:
  2122      if (NODE_BODY(node))
  2123        onig_node_free(NODE_BODY(node));
  2124      break;
  2125
  2126    case NODE_ANCHOR:
  2127      if (NODE_BODY(node))
  2128        onig_node_free(NODE_BODY(node));
  2129      if (IS_NOT_NULL(ANCHOR_(node)->lead_node))
  2130        onig_node_free(ANCHOR_(node)->lead_node);
