  3345  static Node*
  3346  node_new_str(const UChar* s, const UChar* end)
  3347  {
  3348    int r;
  3349    Node* node = node_new();
  3350    CHECK_NULL_RETURN(node);
  3351
  3352    r = node_set_str(node, s, end);
  3353    if (r != 0) {
  3354      onig_node_free(node);
  3355      return NULL;
  3356    }
  3357
  3358    return node;
